  const [expandingArrivalId, setExpandingArrivalId] = React.useState<string | null>(null);
  const [arrivalIsExpanded, setArrivalIsExpanded] = React.useState(false);

  const seenIdsRef = React.useRef<Set<string>>(new Set());
